const app=document.querySelector('#app'),KEY='backend-lab-v1';
let bank=[],state={attempts:[],session:null,last:[]},storageOK=true;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.attempts)&&Array.isArray(s.last))state=s;}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let r=new Uint32Array(1);crypto.getRandomValues(r);const j=Math.floor(r[0]/4294967296*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const topics=()=>[...new Set(bank.map(q=>q.thema))];
const stat=(label,value,sub,cls='')=>`<div class="stat ${cls}"><label>${label}</label><strong>${value}</strong><small>${sub}</small></div>`;
function notice(){return storageOK?'':'<p class="notice" role="alert">Il browser non consente di salvare i progressi. Mantieni aperta questa pagina per conservarli durante la sessione.</p>';}
function home(){const a=state.attempts,correct=a.filter(x=>x.correct).length,seen=new Set(a.map(x=>x.qid)).size,pct=Math.round(seen/bank.length*100);
app.innerHTML=`${notice()}<div class="intro"><div><div class="eyebrow">Il tuo spazio di preparazione</div><h1>Preparati. Mettiti alla prova.</h1><p>Allena le tue conoscenze di backend, un tema alla volta.</p></div><span class="badge">${bank.length} domande &nbsp;·&nbsp; ${topics().length} temi</span></div><div class="stats">${stat('Risposte totali',a.length,'Tutti i tentativi effettuati')}${stat('Risposte corrette',correct,a.length?Math.round(correct/a.length*100)+'% di accuratezza':'Il tuo prossimo obiettivo','correct')}${stat('Risposte sbagliate',a.length-correct,'Ogni errore è un punto di partenza','wrong')}${stat('Domande uniche affrontate',seen+' <small>/ '+bank.length+'</small>','La tua copertura del programma')}</div><div class="session-grid"><section class="hero"><div><div class="eyebrow">Modalità esame</div><h2>Pronto per la prossima sfida?</h2><p>40 domande casuali da tutti i temi. Metti alla prova la tua preparazione e scopri il risultato alla fine.</p><div class="badge">40 DOMANDE &nbsp; / &nbsp; ORDINE CASUALE</div><br><button class="primary" id="start">Avvia simulazione &nbsp; ↗</button></div><div class="hero-graphic"><strong>40</strong><span>DOMANDE</span></div></section><section class="coverage"><div class="coverage-head"><h3>Il tuo percorso</h3><span>${pct}%</span></div><div class="bar"><i style="width:${pct}%"></i></div><strong>${seen} di ${bank.length} domande esplorate</strong><p>${bank.length-seen?`Ci sono ancora ${bank.length-seen} domande da scoprire. Continua ad allenarti per completare il programma.`:'Hai esplorato tutto il programma! Continua ad allenarti per consolidare le conoscenze.'}</p>${state.session?'<button id="resume" style="margin-top:17px">Riprendi la sessione in corso →</button>':''}</section></div><section id="themes"><div class="section-head"><div><h2>Un tema alla volta.</h2><p>Scegli un argomento e concentrati su ciò che vuoi migliorare.</p></div><small>${topics().length} temi disponibili</small></div><div class="topics">${topics().map((t,i)=>{let qs=bank.filter(q=>q.thema===t),n=new Set(a.filter(x=>x.theme===t).map(x=>x.qid)).size;return `<article class="topic"><div class="topic-top"><span class="icon">${['{ }','⌘','!','▤','↗','◇','▦','◫','/ /','⇄'][i]}</span><small>${qs.length} domande</small></div><h3>${esc(t)}</h3><div class="topic-bottom"><span>${n} / ${qs.length} affrontate</span><button data-topic="${i}">Allenati &nbsp; ↗</button></div></article>`;}).join('')}</div></section><section><div class="section-head"><div><h2>I tuoi progressi, per tema.</h2><p>Le risposte ripetute contano come nuovi tentativi.</p></div><button class="reset" id="reset">↺ &nbsp; Azzera statistiche</button></div><div class="table-wrap"><table><thead><tr><th>Tema</th><th>Risposte</th><th>Corrette</th><th>Errori</th><th>Accuratezza</th></tr></thead><tbody>${topics().map(t=>{const x=a.filter(a=>a.theme===t),c=x.filter(a=>a.correct).length;return `<tr><td>${esc(t)}</td><td>${x.length}</td><td>${c}</td><td class="error-num">${x.length-c}</td><td>${x.length?Math.round(c/x.length*100)+'%':'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`;
document.querySelector('#start').onclick=()=>start(null);document.querySelector('#resume')?.addEventListener('click',quiz);document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>start(topics()[+b.dataset.topic]));document.querySelector('#reset').onclick=()=>document.querySelector('#reset-dialog').showModal();}
function start(theme){if(state.session&&!confirm('Una sessione è già in corso. Vuoi sostituirla? Le risposte già confermate resteranno nelle statistiche.'))return;const pool=bank.filter(q=>!theme||q.thema===theme);let ids=shuffle(pool).slice(0,40).map(q=>q.id);if(ids.length>1&&ids.join()===state.last.join())[ids[0],ids[1]]=[ids[1],ids[0]];state.last=ids;state.session={ids,theme,index:0,answers:{},drafts:{},orders:Object.fromEntries(ids.map(id=>[id,shuffle(bank.find(q=>q.id===id).antworten.map(a=>a.id))])),started:Date.now()};save();quiz();window.scrollTo(0,0);}
function quiz(){const s=state.session;if(!s)return home();const q=bank.find(q=>q.id===s.ids[s.index]),answered=s.answers[q.id],n=Object.keys(s.answers).length,training=!!s.theme;
app.innerHTML=`<div class="quiz">${notice()}<div class="quiz-top"><button id="back-home">← Panoramica</button><span class="badge">${training?'Allenamento per tema':'Simulazione d’esame'} · ${n}/${s.ids.length} confermate</span></div><div class="bar"><i style="width:${n/s.ids.length*100}%"></i></div><div class="question-card"><div class="eyebrow">Domanda ${s.index+1} di ${s.ids.length}</div><p style="font-size:12px;margin:12px 0">${esc(q.thema)}</p><h1 lang="de">${esc(q.frage)}</h1><div role="group" aria-label="Risposte">${s.orders[q.id].map((id,i)=>{let a=q.antworten.find(a=>a.id===id),sel=s.drafts[q.id]===id;return `<button lang="de" class="answer ${sel?'selected':''} ${answered&&training?(a.correct?'right':answered.answerId===id?'incorrect':''):''}" data-answer="${id}" aria-pressed="${sel}" ${answered?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(a.frage)}</span></button>`;}).join('')}</div>${answered?(training?`<div class="feedback ${answered.correct?'':'bad'}" role="status">${answered.correct?'✓ Risposta corretta!':'La risposta non è corretta.'}${!answered.correct?'<br>Risposta corretta: '+esc(q.antworten.find(a=>a.correct).frage):''}</div>`:'<div class="feedback" role="status">Risposta registrata. La correzione sarà disponibile alla fine.</div>'):''}<div class="actions"><button id="prev" ${s.index===0?'disabled':''}>← Indietro</button>${!answered?`<button class="dark" id="confirm" ${s.drafts[q.id]===undefined?'disabled':''}>Conferma risposta</button>`:`<button class="dark" id="next">${s.index===s.ids.length-1?'Vai al riepilogo':'Prossima →'}</button>`}</div></div><div class="navigator" aria-label="Navigazione domande">${s.ids.map((id,i)=>`<button data-index="${i}" class="${s.answers[id]?'done':''} ${i===s.index?'current':''}" aria-label="Domanda ${i+1}${s.answers[id]?', risposta confermata':''}">${i+1}</button>`).join('')}</div><div class="actions"><button id="finish">${n===s.ids.length?'Concludi sessione':'Termina e correggi'}</button></div><p style="font-size:11px;margin-top:20px">Le risposte confermate sono definitive e aggiornano subito le statistiche. Le domande senza risposta non vengono contate come errori.</p></div>`;
document.querySelector('#back-home').onclick=home;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{s.drafts[q.id]=+b.dataset.answer;save();quiz();});document.querySelector('#confirm')?.addEventListener('click',()=>{if(s.answers[q.id]||s.drafts[q.id]===undefined)return;const id=s.drafts[q.id],correct=q.antworten.find(a=>a.id===id).correct;s.answers[q.id]={answerId:id,correct};state.attempts.push({qid:q.id,theme:q.thema,correct,at:Date.now()});save();quiz();});document.querySelector('#prev').onclick=()=>go(s.index-1);document.querySelector('#next')?.addEventListener('click',()=>s.index===s.ids.length-1?finish():go(s.index+1));document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>go(+b.dataset.index));document.querySelector('#finish').onclick=finish;}
function go(i){state.session.index=i;save();quiz();}
function finish(){const s=state.session,n=Object.keys(s.answers).length;if(n<s.ids.length&&!confirm(`Hai confermato ${n} risposte su ${s.ids.length}. Vuoi terminare? Le ${s.ids.length-n} domande senza risposta resteranno escluse dalle statistiche.`))return;const c=Object.values(s.answers).filter(a=>a.correct).length;const snapshot=structuredClone(s);state.session=null;save();app.innerHTML=`<div class="quiz"><div class="result"><div class="eyebrow">Sessione completata</div><h1>${n?Math.round(c/n*100):0}%</h1><h2>Un altro passo avanti.</h2><p>${c} risposte corrette su ${n} confermate · ${s.ids.length-n} senza risposta</p><div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Corrette',c,'Risposte confermate','correct')}${stat('Sbagliate',n-c,'Da ripassare','wrong')}${stat('Senza risposta',s.ids.length-n,'Escluse dalle statistiche')}</div><button class="dark" id="again">Nuova sessione ↗</button> <button id="dashboard">Torna alla panoramica</button></div><h2>Rivedi le tue risposte</h2>${snapshot.ids.map((id,i)=>{const q=bank.find(q=>q.id===id),a=snapshot.answers[id];return `<article class="review"><div class="eyebrow">${i+1} · ${a?(a.correct?'✓ Corretta':'✕ Sbagliata'):'Senza risposta'}</div><h3 lang="de" style="margin-top:12px">${esc(q.frage)}</h3>${a?'<p>La tua risposta: '+esc(q.antworten.find(x=>x.id===a.answerId).frage)+'</p>':''}<p style="color:#32764f">Risposta corretta: <span lang="de">${esc(q.antworten.find(x=>x.correct).frage)}</span></p></article>`;}).join('')}</div>`;document.querySelector('#dashboard').onclick=home;document.querySelector('#again').onclick=()=>start(snapshot.theme);window.scrollTo(0,0);}
document.querySelector('#home-link').onclick=e=>{e.preventDefault();home();};document.querySelector('.brand').onclick=e=>{e.preventDefault();home();};document.querySelector('nav a:last-child').onclick=e=>{e.preventDefault();home();document.querySelector('#themes').scrollIntoView({behavior:'smooth'});};document.querySelector('#cancel-reset').onclick=()=>document.querySelector('#reset-dialog').close();document.querySelector('#confirm-reset').onclick=()=>{state={attempts:[],session:null,last:[]};save();document.querySelector('#reset-dialog').close();home();};
try{const res=await fetch('fragen.json');if(!res.ok)throw Error('JSON non disponibile');bank=await res.json();if(!Array.isArray(bank)||!bank.length||bank.some(q=>!q.thema||!Array.isArray(q.antworten)||q.antworten.filter(a=>a.correct).length!==1))throw Error('Formato delle domande non valido');if(state.session&&!state.session.ids.every(id=>bank.some(q=>q.id===id)))state.session=null;home();}catch(e){app.innerHTML='<div class="empty"><h1>Impossibile caricare le domande</h1><p>Controlla la connessione e ricarica la pagina.</p><button onclick="location.reload()">Riprova</button></div>';console.error(e);}
